40|   quarterly(quarter: unknown): QuarterlyReport {
41|     const { year, q } = parseQuarter(quarter);
42|     const start = Date.UTC(year, (q - 1) * 3, 1);
43|     const end = Date.UTC(year, q * 3, 1);
44|     const inQuarter = (date: string): boolean => {
45|       const at = Date.parse(date);
46|       return at >= start && at < end;
47|     };
48|     const productNames = new Map(this.products.findAll().map((p) => [p.id, p.name]));
49|     const regionOf = new Map(this.apiaries.findAll().map((a) => [a.id, a.region]));
50| 
51|     const regions = new Map<string, RegionReport>();
52|     const flagged = new Map<string, number>();
53|     for (const hive of this.hives.findAll()) {
54|       const region = regionOf.get(hive.apiaryId);
55|       if (region === undefined) continue;
56|       let report = regions.get(region);
57|       if (!report) {
58|         report = {
59|           region,
60|           hives: 0,
61|           varroaFlaggedShare: 0,
62|           treatmentsPerProduct: {},
63|           honeyKilograms: 0,
64|         };
65|         regions.set(region, report);
66|       }
67|       report.hives += 1;
68|       if (this.hiveService.isFlagged(hive.id, end)) {
69|         flagged.set(region, (flagged.get(region) ?? 0) + 1);
70|       }
71|       for (const t of this.treatments.findByHive(hive.id)) {
72|         if (!inQuarter(t.startDate)) continue;
73|         const name = productNames.get(t.productId) ?? t.productId;
74|         report.treatmentsPerProduct[name] = (report.treatmentsPerProduct[name] ?? 0) + 1;
75|       }
76|       for (const h of this.harvests.findByHive(hive.id)) {
77|         if (inQuarter(h.date)) report.honeyKilograms += h.kilograms;
78|       }
79|     }
80|     for (const report of regions.values()) {
81|       report.varroaFlaggedShare = (flagged.get(report.region) ?? 0) / report.hives;
82|     }
83|     return {
84|       quarter: `${year}-Q${q}`,
85|       regions: [...regions.values()].sort((a, b) => a.region.localeCompare(b.region)),
86|     };
87|   }
88| }
